package com.thumb.rhythm.audiotest;

import android.util.Base64;
import java.io.File;
import java.io.FileOutputStream;

final class DrumSamples {
    static final String HAT_B64 = "";
    static final String STICK_B64 = "";

    static File write(File dir, String name, String b64) throws Exception {
        File f = new File(dir, name);
        byte[] data = Base64.decode(b64, Base64.DEFAULT);
        try (FileOutputStream out = new FileOutputStream(f)) {
            out.write(data);
        }
        return f;
    }

    private DrumSamples() {}
}
